using System;
using System.Collections.Generic;
using Light.Utilities;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

namespace Light.UI;

/// <summary>
/// 图片画廊面板，参考 FinalSuspect 的 MainMenuStylePanel。
/// 克隆 accountButtons 结构，中间显示预览图，下方大字名称 + 作者，
/// 左右切换按钮，应用/下载按钮，返回按钮。
/// 通过 <see cref="AddImage"/> 注册图片条目，图片为嵌入资源。
/// </summary>
public class ImageGalleryPanel
{
    /// <summary>
    /// 单张图片条目
    /// </summary>
    public class ImageEntry
    {
        public string ResourcePath = "";
        public string Name = "";
        public string Author = "";
        public Action<int>? OnDownload;
    }

    private readonly GameObject _panel;
    private readonly Transform _buttonTemplate;
    private readonly List<ImageEntry> _entries = new();
    private int _currentIndex;
    private int _appliedIndex = -1;
    private Action<int>? _onApply;
    private int _btnIndex;

    private SpriteRenderer _previewImage = null!;
    private TextMeshPro _nameText = null!;
    private TextMeshPro _authorText = null!;
    private TextMeshPro _applyButtonText = null!;

    public GameObject Panel => _panel;
    public int CurrentIndex => _currentIndex;
    public int AppliedIndex => _appliedIndex;

    /// <summary>
    /// 创建画廊面板。
    /// </summary>
    /// <param name="instance">MainMenuManager 实例（用于克隆 accountButtons）</param>
    /// <param name="panelName">面板 GameObject 名称</param>
    /// <param name="title">面板标题</param>
    public ImageGalleryPanel(MainMenuManager instance, string panelName, string title)
    {
        _panel = GameObject.Instantiate(instance.accountButtons,
            instance.accountButtons.transform.parent);
        _panel.name = panelName;

        // 标题
        var titleText = _panel.transform.GetChild(0).GetChild(0)
            .GetComponent<TextMeshPro>();
        if (titleText != null) titleText.text = title;
        var titleTrans = _panel.transform.GetChild(0).GetChild(0)
            .GetComponent<TextTranslatorTMP>();
        if (titleTrans != null) titleTrans.enabled = false;

        // 删除第4个孩子
        var child4 = _panel.transform.GetChild(4);
        if (child4 != null) GameObject.Destroy(child4.gameObject);

        // 按钮模板（第3个孩子）
        _buttonTemplate = _panel.transform.GetChild(3);

        // ── 预览图（SpriteRenderer）──
        var imgObj = UnityHelper.CreateObject<SpriteRenderer>(
            "GalleryPreview", _panel.transform, new Vector3(0f, 0.2f, 0f));
        imgObj.color = Color.white;
        _previewImage = imgObj;

        // ── 名字（大字）── 克隆标题文本 ──
        var titleGO = _panel.transform.GetChild(0).GetChild(0).gameObject;
        var nameObj = GameObject.Instantiate(titleGO, _panel.transform);
        nameObj.name = "GalleryName";
        nameObj.transform.localPosition = new Vector3(0f, -0.85f, 0f);
        nameObj.transform.localScale = new Vector3(1.2f, 1.2f, 1f);
        _nameText = nameObj.GetComponent<TextMeshPro>();
        if (_nameText != null)
        {
            _nameText.text = "";
            _nameText.alignment = TextAlignmentOptions.Center;
            _nameText.fontSize = 3f;
            _nameText.fontStyle = FontStyles.Bold;
        }
        var nameTrans = nameObj.GetComponent<TextTranslatorTMP>();
        if (nameTrans != null) nameTrans.enabled = false;

        // ── 作者 ──
        var authorObj = GameObject.Instantiate(titleGO, _panel.transform);
        authorObj.name = "GalleryAuthor";
        authorObj.transform.localPosition = new Vector3(0f, -1.25f, 0f);
        authorObj.transform.localScale = new Vector3(0.7f, 0.7f, 1f);
        _authorText = authorObj.GetComponent<TextMeshPro>();
        if (_authorText != null)
        {
            _authorText.text = "";
            _authorText.alignment = TextAlignmentOptions.Center;
            _authorText.fontSize = 1.8f;
        }
        var authorTrans = authorObj.GetComponent<TextTranslatorTMP>();
        if (authorTrans != null) authorTrans.enabled = false;

        // ── 左右导航按钮 ──
        CreateNavButton("←", new Vector3(-1.9f, 0.2f, 0f), () => SwitchPage(-1));
        CreateNavButton("→", new Vector3(1.9f, 0.2f, 0f), () => SwitchPage(1));

        // ── 应用按钮 ──
        var applyObj = CreateButtonObject("应用", new Vector3(0.8f, -1.6f, 0f), () =>
        {
            _appliedIndex = _currentIndex;
            UpdateApplyButtonText();
            _onApply?.Invoke(_currentIndex);
        });
        _applyButtonText = applyObj.transform.GetChild(0).GetChild(0)
            .GetComponent<TextMeshPro>();

        // ── 下载按钮 ──
        CreateButtonObject("下载", new Vector3(-0.8f, -1.6f, 0f), () =>
        {
            if (_currentIndex >= 0 && _currentIndex < _entries.Count)
                _entries[_currentIndex].OnDownload?.Invoke(_currentIndex);
        });

        _panel.SetActive(false);
    }

    /// <summary>
    /// 创建按钮（基于 accountButtons 模板克隆）。
    /// </summary>
    private GameObject CreateButtonObject(string text, Vector3 position, Action clickAction)
    {
        GameObject obj = _buttonTemplate.gameObject;
        if (_btnIndex > 0) obj = GameObject.Instantiate(obj, obj.transform.parent);

        var tmp = obj.transform.GetChild(0).GetChild(0).GetComponent<TextMeshPro>();
        if (tmp != null) tmp.text = text;
        var tr = obj.transform.GetChild(0).GetChild(0)
            .GetComponent<TextTranslatorTMP>();
        if (tr != null) tr.enabled = false;

        var pb = obj.GetComponent<PassiveButton>();
        pb.OnClick = new Button.ButtonClickedEvent();
        pb.OnClick.AddListener((UnityAction)(() => clickAction()));

        obj.transform.localPosition = position;
        obj.transform.localScale = new Vector3(0.72f, 0.72f, 1f);
        _btnIndex++;
        return obj;
    }

    /// <summary>
    /// 创建导航按钮（比普通按钮小）。
    /// </summary>
    private void CreateNavButton(string text, Vector3 position, Action clickAction)
    {
        var obj = CreateButtonObject(text, position, clickAction);
        obj.transform.localScale = new Vector3(0.5f, 0.5f, 1f);
    }

    // ════════════════════════════════════════════
    //  公共 API
    // ════════════════════════════════════════════

    /// <summary>
    /// 添加一张图片。
    /// </summary>
    /// <param name="resourcePath">嵌入资源路径（如 Light.Resources.BG.Image1.png）</param>
    /// <param name="name">图片名称（大字显示）</param>
    /// <param name="author">作者名（显示为 "by {author}"）</param>
    /// <param name="onDownload">下载回调，参数为当前图片索引</param>
    public void AddImage(string resourcePath, string name, string author,
        Action<int>? onDownload = null)
    {
        _entries.Add(new ImageEntry
        {
            ResourcePath = resourcePath,
            Name = name,
            Author = author,
            OnDownload = onDownload
        });
    }

    /// <summary>
    /// 设置应用回调。点击"应用"时调用，参数为当前图片索引。
    /// </summary>
    public void SetApplyCallback(Action<int> onApply) => _onApply = onApply;

    /// <summary>
    /// 标记指定索引的图片为已应用（不触发回调）。
    /// </summary>
    public void SetApplied(int index)
    {
        _appliedIndex = index;
        UpdateApplyButtonText();
    }

    /// <summary>
    /// 添加返回按钮。
    /// </summary>
    /// <param name="targetPanel">返回时显示的面板</param>
    /// <param name="position">自定义坐标，为 null 时放在底部居中</param>
    public void AddBackButton(GameObject targetPanel, Vector3? position = null)
    {
        CreateButtonObject("返回", position ?? new Vector3(0f, -2.1f, 0f), () =>
        {
            _panel.SetActive(false);
            targetPanel.SetActive(true);
        });
    }

    // ════════════════════════════════════════════
    //  内部逻辑
    // ════════════════════════════════════════════

    private void SwitchPage(int delta)
    {
        if (_entries.Count == 0) return;
        _currentIndex = (_currentIndex + delta + _entries.Count) % _entries.Count;
        Refresh();
    }

    private void Refresh()
    {
        if (_currentIndex < 0 || _currentIndex >= _entries.Count) return;
        var entry = _entries[_currentIndex];

        // 更新预览图
        var spr = ResourceHelper.LoadSpriteFromResource(entry.ResourcePath);
        if (spr != null)
        {
            _previewImage.sprite = spr;
            // 等比缩放至显示区域
            float maxW = 2.6f, maxH = 1.5f;
            float texW = spr.texture.width, texH = spr.texture.height;
            float scaleX = maxW / (texW / 100f);
            float scaleY = maxH / (texH / 100f);
            float scale = Mathf.Min(scaleX, scaleY);
            _previewImage.transform.localScale = new Vector3(scale, scale, 1f);
        }

        // 更新文字
        if (_nameText != null) _nameText.text = entry.Name;
        if (_authorText != null) _authorText.text = "by " + entry.Author;

        UpdateApplyButtonText();
    }

    private void UpdateApplyButtonText()
    {
        if (_applyButtonText != null)
            _applyButtonText.text = _currentIndex == _appliedIndex ? "已应用" : "应用";
    }

    // ════════════════════════════════════════════
    //  面板控制
    // ════════════════════════════════════════════

    public void RegisterToScaler()
    {
        var scalerList = GameObject.FindObjectOfType<SlicedAspectScaler>();
        if (scalerList != null)
            foreach (var asset in _panel.GetComponentsInChildren<AspectScaledAsset>())
                scalerList.objectsToScale.Add(asset);
    }

    public void Show()
    {
        if (_currentIndex >= _entries.Count) _currentIndex = 0;
        Refresh();
        _panel.SetActive(true);
    }

    public void Hide() => _panel.SetActive(false);
}

