using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Security.Cryptography;
using LightInDark.Core;
using LightInDark.UI.Window;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

namespace Light.UI;

public class ImageGalleryPanel
{
    public class ImageEntry
    {
        public string Name = "";
        public string Author = "";
        public string Hash = "";
        public Action<int>? OnDownload;
    }

    private const string ResourcePrefix = "Light.Resources.MainMenuBackground.BG_";
    private const string DefaultName = "Default";

    private readonly GameObject _panel;
    private readonly List<ImageEntry> _entries = new();
    private int _currentIndex;
    private int _appliedIndex = -1;
    private Action<int>? _onApply;
    private Action? _onHashFailedFallback;
    private string _defaultHash = "";

    private SpriteRenderer _previewImage = null!;
    private TextMeshPro _nameText = null!;
    private TextMeshPro _authorText = null!;
    private TextMeshPro _applyText = null!;
    private GameObject _emptyHint = null!;

    public GameObject Panel => _panel;
    public int CurrentIndex => _currentIndex;
    public int AppliedIndex => _appliedIndex;

    public ImageGalleryPanel(MainMenuManager instance, string panelName, string title)
    {
        _panel = GameObject.Instantiate(instance.accountButtons,
            instance.accountButtons.transform.parent);
        _panel.name = panelName;

        var titleText = _panel.transform.GetChild(0).GetChild(0).GetComponent<TextMeshPro>();
        if (titleText != null) titleText.text = title;
        var titleTrans = _panel.transform.GetChild(0).GetChild(0)
            .GetComponent<TextTranslatorTMP>();
        if (titleTrans != null) titleTrans.enabled = false;

        var child4 = _panel.transform.GetChild(4);
        if (child4 != null) GameObject.Destroy(child4.gameObject);
        _panel.transform.GetChild(3).gameObject.SetActive(false);

        var titleGO = _panel.transform.GetChild(0).GetChild(0).gameObject;

        _previewImage = CreatePreviewImage();
        _nameText = CreateText(titleGO, "GalleryName", new Vector3(0f, -0.7f, -0.1f),
            new Vector3(1.2f, 1.2f, 1f), 3f, FontStyles.Bold);
        _authorText = CreateText(titleGO, "GalleryAuthor", new Vector3(0f, -1.1f, -0.1f),
            new Vector3(0.7f, 0.7f, 1f), 1.8f, FontStyles.Normal);

        _emptyHint = CreateText(titleGO, "EmptyHint", new Vector3(0f, 0.3f, -0.1f),
            Vector3.one, 2.5f, FontStyles.Bold);
        _emptyHint.text = "暂无图片";
        _emptyHint.gameObject.SetActive(false);

        CreateNavButton(instance, true, new Vector3(-2.0f, 0.4f, -0.1f), () => SwitchPage(-1));
        CreateNavButton(instance, false, new Vector3(2.0f, 0.4f, -0.1f), () => SwitchPage(1));

        var applyObj = CloneButton(instance, "应用", new Vector3(1.0f, -1.6f, -0.1f), () =>
        {
            _appliedIndex = _currentIndex;
            UpdateApplyText();
            ApplyBackground();
            _onApply?.Invoke(_currentIndex);
        });
        _applyText = GetButtonText(applyObj);

        CloneButton(instance, "下载", new Vector3(-1.0f, -1.6f, -0.1f), () =>
        {
            if (_currentIndex >= 0 && _currentIndex < _entries.Count)
                _entries[_currentIndex].OnDownload?.Invoke(_currentIndex);
        });

        _appliedIndex = 0;
        _panel.SetActive(false);
    }

    private SpriteRenderer CreatePreviewImage()
    {
        var obj = new GameObject("GalleryPreview");
        obj.layer = LayerExpansion.GetUILayer();
        obj.transform.SetParent(_panel.transform, false);
        obj.transform.localPosition = new Vector3(0f, 0.4f, 0f);
        var sr = obj.AddComponent<SpriteRenderer>();
        sr.color = Color.white;
        return sr;
    }

    private TextMeshPro CreateText(GameObject template, string name, Vector3 pos,
        Vector3 scale, float fontSize, FontStyles style)
    {
        var obj = GameObject.Instantiate(template, _panel.transform);
        obj.name = name;
        obj.transform.localPosition = pos;
        obj.transform.localScale = scale;
        var tmp = obj.GetComponent<TextMeshPro>();
        if (tmp != null)
        {
            tmp.text = "";
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.fontSize = fontSize;
            tmp.fontStyle = style;
        }
        var tr = obj.GetComponent<TextTranslatorTMP>();
        if (tr != null) tr.enabled = false;
        return tmp!;
    }

    private GameObject CloneButton(MainMenuManager instance, string text,
        Vector3 position, Action clickAction)
    {
        var clone = GameObject.Instantiate(instance.quitButton.gameObject,
            instance.quitButton.transform.parent);
        clone.name = text;
        clone.transform.localPosition = position;
        clone.transform.localScale = new Vector3(0.6f, 0.6f, 1f);

        var fp = clone.transform.FindChild("FontPlacer");
        if (fp != null && fp.childCount > 0)
        {
            var tmp = fp.GetChild(0).GetComponent<TextMeshPro>();
            if (tmp != null) tmp.text = text;
            var tr = fp.GetChild(0).GetComponent<TextTranslatorTMP>();
            if (tr != null) tr.enabled = false;
        }

        var pb = clone.GetComponent<PassiveButton>();
        pb.OnClick = new Button.ButtonClickedEvent();
        pb.OnClick.AddListener((UnityAction)(() => clickAction()));

        var pink = new Color32(255, 192, 203, 255);
        FormatButton(pb, pink);

        return clone;
    }

    private void CreateNavButton(MainMenuManager instance, bool isLeft,
        Vector3 position, Action clickAction)
    {
        var clone = CloneButton(instance, isLeft ? "←" : "→", position, clickAction);
        clone.transform.localScale = new Vector3(0.4f, 0.4f, 1f);
    }

    private void FormatButton(PassiveButton btn, Color32 color)
    {
        if (btn.activeSprites != null)
        {
            var sr = btn.activeSprites.GetComponent<SpriteRenderer>();
            if (sr != null) sr.color = color;
            btn.activeSprites.transform.FindChild("Shine")?.gameObject.SetActive(false);
        }
        if (btn.inactiveSprites != null)
        {
            var sr = btn.inactiveSprites.GetComponent<SpriteRenderer>();
            if (sr != null) sr.color = color;
            btn.inactiveSprites.transform.FindChild("Shine")?.gameObject.SetActive(false);
        }
        btn.activeTextColor = Color.white;
        btn.inactiveTextColor = Color.white;
    }

    private static TextMeshPro GetButtonText(GameObject btn)
    {
        var fp = btn.transform.FindChild("FontPlacer");
        if (fp != null && fp.childCount > 0)
            return fp.GetChild(0).GetComponent<TextMeshPro>();
        return null!;
    }

    // ════════════════════════════════════════════
    //  Public API
    // ════════════════════════════════════════════

    public void AddImage(string name, string author, string hash,
        Action<int>? onDownload = null)
    {
        _entries.Add(new ImageEntry
        {
            Name = name,
            Author = author,
            Hash = hash,
            OnDownload = onDownload
        });
    }

    public void SetApplyCallback(Action<int> onApply) => _onApply = onApply;
    public void SetDefaultHash(string hash) => _defaultHash = hash;
    public void SetHashFailedFallback(Action fallback) => _onHashFailedFallback = fallback;

    public void AddBackButton(GameObject targetPanel, Vector3? position = null)
    {
        CloneButton(GetMainMenuManager(), "返回",
            position ?? new Vector3(0f, -2.1f, -0.1f), () =>
            {
                _panel.SetActive(false);
                targetPanel.SetActive(true);
            });
    }

    // ════════════════════════════════════════════
    //  Image loading with hash verification
    // ════════════════════════════════════════════

    private static byte[] ReadResourceBytes(string resourcePath)
    {
        var assembly = Assembly.GetExecutingAssembly();
        using var stream = assembly.GetManifestResourceStream(resourcePath);
        if (stream == null) return null!;
        var bytes = new byte[stream.Length];
        stream.Read(bytes, 0, (int)stream.Length);
        return bytes;
    }

    private static string ComputeHash(byte[] data)
    {
        using var sha = SHA256.Create();
        var hash = sha.ComputeHash(data);
        return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
    }

    private static Sprite BytesToSprite(byte[] bytes)
    {
        var tex = new Texture2D(2, 2, TextureFormat.ARGB32, false);
        if (!ImageConversion.LoadImage(tex, bytes, false)) return null!;
        tex.wrapMode = TextureWrapMode.Clamp;
        return Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height),
            new Vector2(0.5f, 0.5f), 100f);
    }

    private static string ResourcePathFor(string name) =>
        ResourcePrefix + name + ".png";

    private Sprite? LoadVerifiedSprite(string name, string expectedHash)
    {
        var path = ResourcePathFor(name);
        var bytes = ReadResourceBytes(path);
        if (bytes == null)
        {
            LightLogger.LogWarning($"[Gallery] 资源未找到: {path}");
            return TryLoadDefault();
        }

        var actualHash = ComputeHash(bytes);
        if (actualHash == expectedHash.ToLowerInvariant())
            return BytesToSprite(bytes);

        LightLogger.LogWarning($"[Gallery] 哈希不匹配: {name} (期望={expectedHash}, 实际={actualHash})");
        return TryLoadDefault();
    }

    private Sprite? TryLoadDefault()
    {
        var bytes = ReadResourceBytes(ResourcePathFor(DefaultName));
        if (bytes == null)
        {
            LightLogger.LogWarning("[Gallery] BG_Default.png 未找到");
            _onHashFailedFallback?.Invoke();
            return null;
        }

        var actualHash = ComputeHash(bytes);
        if (!string.IsNullOrEmpty(_defaultHash) &&
            actualHash != _defaultHash.ToLowerInvariant())
        {
            LightLogger.LogWarning($"[Gallery] BG_Default 哈希不匹配 (期望={_defaultHash}, 实际={actualHash})");
            _onHashFailedFallback?.Invoke();
            return null;
        }

        return BytesToSprite(bytes);
    }

    // ════════════════════════════════════════════
    //  Background replacement
    // ════════════════════════════════════════════

    private void ApplyBackground()
    {
        if (_currentIndex < 0 || _currentIndex >= _entries.Count) return;
        var entry = _entries[_currentIndex];
        var sprite = LoadVerifiedSprite(entry.Name, entry.Hash);
        if (sprite == null) return;

        var bg = GameObject.Find("BackgroundTexture");
        if (bg == null)
        {
            LightLogger.LogWarning("[Gallery] BackgroundTexture 未找到");
            return;
        }
        var sr = bg.GetComponent<SpriteRenderer>();
        if (sr != null) sr.sprite = sprite;
    }

    public void ApplyDefaultBackground()
    {
        if (_entries.Count == 0) return;
        _currentIndex = 0;
        _appliedIndex = 0;
        ApplyBackground();
    }

    // ════════════════════════════════════════════
    //  Internal
    // ════════════════════════════════════════════

    private void SwitchPage(int delta)
    {
        if (_entries.Count == 0) return;
        _currentIndex = (_currentIndex + delta + _entries.Count) % _entries.Count;
        Refresh();
    }

    private void Refresh()
    {
        bool empty = _entries.Count == 0;
        _emptyHint.gameObject.SetActive(empty);
        _previewImage.gameObject.SetActive(!empty);

        if (empty)
        {
            _nameText.text = "";
            _authorText.text = "";
            return;
        }

        if (_currentIndex < 0 || _currentIndex >= _entries.Count) _currentIndex = 0;
        var entry = _entries[_currentIndex];

        var spr = LoadVerifiedSprite(entry.Name, entry.Hash);
        if (spr != null)
        {
            _previewImage.sprite = spr;
            float maxW = 2.6f, maxH = 1.3f;
            float scaleX = maxW / (spr.texture.width / 100f);
            float scaleY = maxH / (spr.texture.height / 100f);
            float scale = Mathf.Min(scaleX, scaleY);
            _previewImage.transform.localScale = new Vector3(scale, scale, 1f);
        }

        _nameText.text = entry.Name;
        _authorText.text = "by " + entry.Author;
        UpdateApplyText();
    }

    private void UpdateApplyText()
    {
        if (_applyText != null)
            _applyText.text = _currentIndex == _appliedIndex ? "已应用" : "应用";
    }

    private static MainMenuManager GetMainMenuManager() =>
        DestroyableSingleton<MainMenuManager>.Instance;

    public void RegisterToScaler()
    {
        var scalerList = GameObject.FindObjectOfType<SlicedAspectScaler>();
        if (scalerList != null)
            foreach (var asset in _panel.GetComponentsInChildren<AspectScaledAsset>())
                scalerList.objectsToScale.Add(asset);
    }

    public void Show()
    {
        if (_currentIndex >= _entries.Count) _currentIndex = 0;
        Refresh();
        _panel.SetActive(true);
    }

    public void Hide() => _panel.SetActive(false);
}

