using UnityEngine;
using UnityEngine.UI;

namespace Light.Patches;

public class ButtonBreathEffect : MonoBehaviour
{
    private static int _id = 0;
    private int _myId;

    private Vector3 _basePos;
    private Vector3 _baseScale;
    private float _phase;
    private float _hoverLerp;
    private float _clickLerp;

    private SpriteRenderer? _inactiveSr;
    private SpriteRenderer? _activeSr;
    private GameObject? _shine;
    private Color _baseColor;
    private PassiveButton? _button;

    public void Awake()
    {
        _myId = _id++;
        _phase = Random.value * Mathf.PI * 2f;

        _button = GetComponent<PassiveButton>();
        _basePos = transform.localPosition;
        _baseScale = transform.localScale;

        if (_button != null)
        {
            if (_button.inactiveSprites != null)
            {
                _inactiveSr = _button.inactiveSprites.GetComponent<SpriteRenderer>();
                var shine = _button.inactiveSprites.transform.FindChild("Shine");
                if (shine != null)
                {
                    _shine = shine.gameObject;
                    _shine.SetActive(true);
                    _baseColor = _inactiveSr != null ? _inactiveSr.color : Color.white;
                }
            }
            if (_button.activeSprites != null)
                _activeSr = _button.activeSprites.GetComponent<SpriteRenderer>();

            _button.OnMouseOver?.AddListener((UnityEngine.Events.UnityAction)OnHover);
            _button.OnMouseOut?.AddListener((UnityEngine.Events.UnityAction)OnUnhover);
            _button.OnClick?.AddListener((UnityEngine.Events.UnityAction)OnClick);
        }
    }

    private void OnHover()
    {
    }

    private void OnUnhover()
    {
    }

    private void OnClick()
    {
        _clickLerp = 1f;
    }

    public void Update()
    {
        _phase += Time.deltaTime;

        float breath = 0.04f + 0.03f * Mathf.Sin(_phase * 0.8f + _myId);
        float floatY = 0.025f * Mathf.Sin(_phase * 1.2f + _myId * 0.7f);

        bool hovering = _button != null && _button.IsHovered;
        float targetHover = hovering ? 1f : 0f;
        _hoverLerp = Mathf.Lerp(_hoverLerp, targetHover, Time.deltaTime * 10f);

        _clickLerp = Mathf.Lerp(_clickLerp, 0f, Time.deltaTime * 6f);

        float hoverScale = 1f + 0.08f * _hoverLerp;
        float clickScale = 1f - 0.06f * _clickLerp;
        float totalScale = hoverScale * clickScale;

        transform.localScale = _baseScale * (totalScale + breath);
        transform.localPosition = _basePos + new Vector3(0f, floatY, 0f);

        if (_inactiveSr != null)
        {
            float brightness = 1f + 0.15f * Mathf.Sin(_phase * 0.8f + _myId);
            float hoverBoost = 0.2f * _hoverLerp;
            _inactiveSr.color = new Color(
                Mathf.Min01(_baseColor.r * brightness + hoverBoost),
                Mathf.Min01(_baseColor.g * brightness + hoverBoost),
                Mathf.Min01(_baseColor.b * brightness + hoverBoost),
                _baseColor.a
            );
        }

        if (_shine != null && _inactiveSr != null)
        {
            _shine.SetActive(_hoverLerp > 0.01f);
            var sr = _shine.GetComponent<SpriteRenderer>();
            if (sr != null)
            {
                var c = sr.color;
                sr.color = new Color(c.r, c.g, c.b, 0.5f * _hoverLerp);
            }

            if (hovering)
            {
                Vector3 mouseWorld = Camera.main != null
                    ? Camera.main.ScreenToWorldPoint(Input.mousePosition)
                    : Vector3.zero;
                Vector3 local = _shine.transform.parent.InverseTransformPoint(mouseWorld);
                _shine.transform.localPosition = new Vector3(
                    Mathf.Clamp(local.x, -0.5f, 0.5f),
                    Mathf.Clamp(local.y, -0.3f, 0.3f),
                    _shine.transform.localPosition.z
                );
            }
        }
    }
}

