using Il2CppInterop.Runtime.Injection;
using UnityEngine;
using UnityEngine.UI;

namespace Light.Patches;

public class ButtonBreathEffect : MonoBehaviour
{
    static ButtonBreathEffect()
    {
        ClassInjector.RegisterTypeInIl2Cpp<ButtonBreathEffect>();
    }

    private static int _id;
    private int _myId;

    private Vector3 _basePos;
    private Vector3 _baseScale;
    private float _phase;
    private float _hoverLerp;
    private float _clickLerp;
    private bool _isHovering;

    private GameObject? _shine;
    private PassiveButton? _button;

    private const float FollowRadius = 0.15f;
    private const float FloatAmount = 0.005f;
    private const float BreathAmount = 0.008f;

    public void Awake()
    {
        _myId = _id++;
        _phase = UnityEngine.Random.value * Mathf.PI * 2f;

        _button = GetComponent<PassiveButton>();
        _basePos = transform.localPosition;
        _baseScale = transform.localScale;

        if (_button != null)
        {
            if (_button.inactiveSprites != null)
            {
                var shine = _button.inactiveSprites.transform.FindChild("Shine");
                if (shine != null)
                {
                    _shine = shine.gameObject;
                    var sr = _shine.GetComponent<SpriteRenderer>();
                    if (sr != null)
                    {
                        var c = sr.color;
                        sr.color = new Color(c.r, c.g, c.b, 0f);
                    }
                }
            }

            _button.OnMouseOver?.AddListener((UnityEngine.Events.UnityAction)(() => _isHovering = true));
            _button.OnMouseOut?.AddListener((UnityEngine.Events.UnityAction)(() => _isHovering = false));
            _button.OnClick?.AddListener((UnityEngine.Events.UnityAction)(() => _clickLerp = 1f));
        }
    }

    public void Update()
    {
        _phase += Time.deltaTime;

        float breath = BreathAmount + BreathAmount * 0.5f * Mathf.Sin(_phase * 0.8f + _myId);
        float floatY = FloatAmount * Mathf.Sin(_phase * 1.2f + _myId * 0.7f);

        float targetHover = _isHovering ? 1f : 0f;
        _hoverLerp = Mathf.Lerp(_hoverLerp, targetHover, Time.deltaTime * 10f);
        _clickLerp = Mathf.Lerp(_clickLerp, 0f, Time.deltaTime * 6f);

        float hoverScale = 1f + 0.08f * _hoverLerp;
        float clickScale = 1f - 0.06f * _clickLerp;
        float totalScale = hoverScale * clickScale;

        Vector3 pos = _basePos + new Vector3(0f, floatY, 0f);

        if (_isHovering && Camera.main != null)
        {
            Vector3 mouseWorld = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            Vector3 local = transform.parent.InverseTransformPoint(mouseWorld);
            Vector3 delta = local - _basePos;
            float dist = delta.magnitude;
            if (dist > FollowRadius)
                delta = delta.normalized * FollowRadius;
            pos += delta * 0.3f;
        }

        transform.localScale = _baseScale * (totalScale + breath);
        transform.localPosition = pos;

        if (_shine != null)
        {
            _shine.SetActive(_hoverLerp > 0.01f);
            var sr = _shine.GetComponent<SpriteRenderer>();
            if (sr != null)
            {
                var c = sr.color;
                sr.color = new Color(c.r, c.g, c.b, 0.5f * _hoverLerp);
            }

            if (_isHovering && Camera.main != null)
            {
                Vector3 mouseWorld = Camera.main.ScreenToWorldPoint(Input.mousePosition);
                Vector3 local = _shine.transform.parent.InverseTransformPoint(mouseWorld);
                _shine.transform.localPosition = new Vector3(
                    Mathf.Clamp(local.x, -0.5f, 0.5f),
                    Mathf.Clamp(local.y, -0.3f, 0.3f),
                    _shine.transform.localPosition.z
                );
            }
        }
    }
}

