        }
    }

    // 背景视差：鼠标移动时背景微移
    if (_bgMoved)
    {
        var bg = FindGO("BackgroundTexture");
        if (bg != null && Camera.main != null)
        {
            var mousePos = Input.mousePosition;
            var screenCenter = new Vector3(Screen.width * 0.5f, Screen.height * 0.5f, 0f);
            var offset = (mousePos - screenCenter) / screenCenter.magnitude;
            var target = new Vector3(
                _bgBasePos.x + offset.x * 0.3f,
                7.1f + offset.y * 0.2f,
                _bgBasePos.z);
            bg.transform.position = Vector3.Lerp(bg.transform.position, target, Time.deltaTime * 3f);
        }
    }
}

