        while (t != null)
        {
            if (t.name == "OptionsMenu" || t.name == "SettingMenu")
            {
                inOptions = true;
                break;
            }
            t = t.parent;
        }
        if (inOptions) continue;

        go.AddComponent<ButtonBreathEffect>();
    }
}

